/* Shop UI extends the existing financial statements and credit assessment. */
const E=ShopEngine;
const SAVE_KEY='finance-game-v4';
let dialogReturn=null,entryStage=0,storageError='',introEntry=null,introStage=0;
for(const account of ['建物附属設備','給料手当']){if(!debitAccounts.includes(account))debitAccounts.push(account);}
if(!assetAccounts.includes('建物附属設備'))assetAccounts.push('建物附属設備');
if(!expenseAccounts.includes('給料手当'))expenseAccounts.push('給料手当');
descriptions.建物附属設備='倉庫増設の取得原価。購入代金は資産として記録し、毎月償却します。';
descriptions.売上原価='販売分の税抜仕入原価です。期限切れ・陳腐化・死亡は商品廃棄損に分けます。';
const yen=n=>Math.round(n).toLocaleString('ja-JP')+'円';
const icon=(id,cls='')=>id==='fixture'?'<span class="equipment-emoji" aria-hidden="true">🛠️</span>':`<img class="equipment-icon ${cls}" src="assets/equipment/${id}.png" alt="">`;
const productIcon=p=>p.id==='aji'?icon('aji','product-image'):`<span class="product-emoji" aria-hidden="true">${p.icon}</span>`;
function currentAction(){return state.actionLocked||choice.action;}
function toast(message){let t=el('shopToast');if(!t){t=document.createElement('p');t.id='shopToast';t.setAttribute('role','status');document.body.append(t);}t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000);}
function openShop(title,body){dialogReturn=document.activeElement;el('shopDialogTitle').textContent=title;el('shopDialogBody').innerHTML=body;if(!el('shopDialog').open)el('shopDialog').showModal();el('closeShopDialog').focus();}
function showNewGameConfirmation(){
 openShop('最初から始めますか？','<p>現在の経営を終了し、会社設立の説明から新しいゲームを始めます。</p><p>現在のセーブは１世代分だけ退避します。「経営メニュー → セーブ」からダウンロードして復元できます。音の設定は引き継ぎます。</p><p id="newGameError" role="alert"></p><button id="cancelNewGame">やめる・今のゲームを続ける</button><button class="confirm" id="confirmNewGame">最初から始める</button>');
}
function restartGame(){
 try{
  const old=localStorage.getItem(SAVE_KEY);
  if(old)localStorage.setItem(SAVE_KEY+'-before-restore',old);
  localStorage.removeItem(SAVE_KEY);
 }catch{
  el('newGameError').textContent='セーブを退避できなかったため、やり直しを中止しました。経営メニューの「セーブ」で現在の進行を保存し、ブラウザーの保存容量・設定を確認してください。';return;
 }
 // Prevent delayed callbacks from saving the old game while navigation is pending.
 introComplete=false;el('confirmNewGame').disabled=true;location.reload();
}
document.addEventListener('click',event=>{if(event.target.closest('button')?.id==='cancelNewGame')closeShop();});
function closeShop(){el('shopDialog').close();el('shopDialogBody').innerHTML='';dialogReturn?.focus();}
function capacityText(key,u=E.usage(state),c=E.capacities(state)){return key==='dry'?`${(u.dry/4).toLocaleString()} / ${(c.dry/4).toLocaleString()} pt`:key==='cold'?`${u.cold} / ${c.cold} パック`:`${u.water} / ${c.water} 匹`;}
function equipmentDetail(id){const eq=E.EQUIPMENT[id];const key={warehouse:'dry',freezer:'cold',tank:'water'}[id];if(id==='tank'){showTank();return;}openShop(eq.name,`<div class="equipment-hero">${icon(id)}<div><p>${eq.description}</p><b>${key?capacityText(key):'接客上限 ＋350人'}</b></div></div><dl class="equipment-facts"><div><dt>購入代金（税込）</dt><dd>${yen(E.gross(state,eq.cost))}</dd></div><div><dt>毎月の維持費</dt><dd>${yen(eq.upkeep)}</dd></div><div><dt>月次減価償却</dt><dd>${yen(Math.floor(eq.cost/eq.life))}</dd></div></dl>${key?inventoryCards(key):''}`);}
function inventoryCards(storage){return `<div class="inventory-grid">${E.PRODUCTS.filter(p=>!p.retired&&(!storage||p.storage===storage)).map(p=>{const i=E.PRODUCTS.indexOf(p),open=E.unlocked(state,p);return `<button class="inventory-card ${open?'':'locked'}" data-stock="${i}">${productIcon(p)}<span>${p.name}</span><strong>${open?state.inventory[i].toLocaleString()+'<small>'+p.unit+'</small>':'未解放'}</strong></button>`;}).join('')}</div>`;}
function renderOverview(){el('sceneEquipment').innerHTML=Object.keys(state.equipment).map(id=>`<button class="scene-equipment" data-equipment="${id}" aria-label="${E.EQUIPMENT[id].name}の詳細">${icon(id)}<span>${E.EQUIPMENT[id].name}</span></button>`).join('');const limits=E.limits(state,currentAction());el('shopOverview').innerHTML=`<div class="section-head"><h2>店の設備と在庫</h2><button id="investMenu">設備投資</button></div><div class="shop-limits"><span>集客上限 <b>${limits.cap.toLocaleString()}人/月</b></span><span>接客上限 <b>${limits.service.toLocaleString()}人/月</b></span><span>常温保管 <b>${capacityText('dry')}</b></span></div>${inventoryCards()}<p class="inventory-hint">商品・設備をタップすると詳細が開きます。</p>`;
 const b=state.balances;el('compactLedger').innerHTML=`<table><thead><tr><th>主な科目</th><th>金額（千円）</th></tr></thead><tbody>${['預金','売掛金','商品','什器','建物附属設備'].filter(a=>b[a]).map(a=>`<tr><th>${a}</th><td>${amountText(b[a])}</td></tr>`).join('')}<tr class="profit-row"><th>当期損益</th><td>${amountText(accrued(b))}</td></tr></tbody></table>`;}
renderOrders=function(){el('orders').innerHTML=E.PRODUCTS.map((p,i)=>{if(!E.unlocked(state,p))return '';const step=p.id==='rod'||p.id==='reel'?1:10,q=choice.quantities[i]||0;return `<div class="product-order"><div class="product-title">${productIcon(p)}<div><b>${p.name}</b><small>今ある在庫：${state.inventory[i].toLocaleString()}${p.unit}</small><small>１${p.unit}の仕入価格：${yen(p.cost)}（税抜）</small></div></div><div class="order-controls"><label for="orderQuantity${i}">追加で買う数</label><button data-product="${i}" data-step="-${step}" aria-label="${p.name}を${step}${p.unit}減らす" ${q===0?'disabled':''}>−${step}</button><input id="orderQuantity${i}" data-product="${i}" type="number" inputmode="numeric" min="0" max="100000" step="1" value="${q}" aria-label="${p.name}の追加仕入数量"><span class="order-unit">${p.unit}</span><button data-product="${i}" data-step="${step}" aria-label="${p.name}を${step}${p.unit}増やす">＋${step}</button><b class="order-subtotal">支払予定：${yen(E.gross(state,q*p.cost))}</b></div></div>`;}).join('');el('orderTotal').textContent=yen(orderCost());};
setQuantity=function(i,value){if(!Number.isInteger(i)||i<0||i>=E.PRODUCTS.length)return false;if(state.closed||state.ended)return false;const n=Number(value);if(value===''||!Number.isSafeInteger(n)||n<0||n>100000){toast('仕入数量は0から100,000までの整数で入力してください。');renderPlanning();return false;}choice.quantities[i]=n;choice.orderSource='manual';renderPlanning();saveGame();return true;};
actionCost=function(){return E.gross(state,E.promotionCost(currentAction()));};
animateScene=function(){clearTimeout(sceneTimer);const a=currentAction();el('scene').className='scene stocked '+(a==='tend'||a==='improve'||state.staff.length?'busy':'owner-away');el('sceneActivity').textContent=a==='improve'?'クエが販促・接客改善中（短縮営業）':a==='tend'?`クエが店番 · 従業員${state.staff.length}人`:state.staff.length?'社長は店外へ · 従業員が店番':'社長は店外へ · 今月は休業';};
renderTutorial=function(){
 const target=el('tutorialPlanning'),i=Math.min(11,state.turn-1),m=month(state.turn),due=t=>state.receivables.filter(x=>x.due===t).reduce((n,x)=>n+x.amount,0),lessons=[
  ['売上・利益・現金は別もの','現金売上は今月の預金、カード売上は売掛金になります。販売時に利益へ入り、入金は２か月後です。'],
  ['入金までのつなぎ','先月のカード売上はまだ未入金です。仕入代金は今月すぐ払うため、売上があっても預金が減ることがあります。'],
  ['回収は新しい売上ではない','４月のカード代金を回収します。仕訳は「預金／売掛金」。販売月に計上済みなので、今月の売上にはしません。'],
  ['粗利率と粗利額','値上げは１個あたりの粗利率を上げますが、販売数量が落ちれば粗利額は減ります。商品別の売上見込みも比べましょう。'],
  ['夏の好調と過剰在庫','夏の売上に合わせた仕入を冬まで続けると、商品に預金が寝ます。売れ残りと廃棄予定を確認しましょう。'],
  ['品揃えと回転','扱える全種類が月末に１つ以上残れば、集客力の自然減は０です。種類を保ちつつ、数量を抱えすぎないのがポイントです。'],
  ['冬前の資金計画','冬は売上が急減します。仕入だけでなく、返済・税金・固定費を含む月末預金を確認しましょう。'],
  ['営業努力は遅れて実る','販促・接客改善は今月すぐ集客を増やしません。翌月と翌々月に効果が出て、３・４か月後に減衰し、５か月後に直接効果が消えます。'],
  ['冬の赤字を分解する','赤字の原因を客数、粗利、固定費、廃棄に分けます。季節減と営業不足を同じ原因にしないでください。'],
  ['個人と会社は別財布','生活費は会社の経費ではありません。役員報酬で足りず会社から借りると、役員貸付金になり銀行審査へ響きます。'],
  ['融資は返せる額まで','２年目の創業赤字融資は、直近の確定２か月がそれぞれ黒字であることが条件です。借入は利益ではありません。'],
  ['決算と翌期への繰越','３月は年次決算です。損益を利益剰余金へ振り替え、税金は未払計上して５月の支払へ備えます。']
 ],[title,body]=lessons[i]||lessons.at(-1),winter=[12,1,2].includes(m),spend=orderCost(),fixed=E.fixedCosts(state),after=cash()-spend-actionCost()-E.scheduled(state).principal-E.scheduled(state).interest-E.scheduled(state).tax-fixed;
 target.hidden=state.turn>12;if(target.hidden)return;
 target.innerHTML=`<details open><summary>Q：${title}</summary><p>${body}</p>${state.turn<=3?`<div class="payment-timeline"><div><b>今月 ${m}月</b><span class="negative">仕入支払 ${spend? '▲'+fmt(spend):'0千円'}</span></div><div><b>来月 ${month(state.turn+1)}月</b><span>今月のカード代は入金待ち</span></div><div><b>２か月後 ${month(state.turn+2)}月</b><span class="positive">カード代金を回収</span></div></div><p>確定済みの回収予定：今月 ${fmt(due(state.turn))}／来月 ${fmt(due(state.turn+1))}／再来月 ${fmt(due(state.turn+2))}</p>`:''}<p class="learning-budget">確定支払後の預金目安 <b class="${after<0?'negative':''}">${fmt(after)}</b></p>${winter?'<p>冬の需要は夏の半分以下。前月数量のまま確定せず、補充案と在庫を見直しましょう。</p>':''}<details><summary>集客と営業努力の詳しいルール</summary><p>全種類の月末在庫で自然減を止められます。営業努力は翌月から２か月維持、その後減衰して５か月後に消滅、夏のセールによるリピーター効果は翌年の同じ季節から出ます。販促で来店したお客さんに販売できれば、お店の認知は少しずつ残ります。広告の直接効果とは別です。</p></details></details>`;
};
renderTutorialReport=function(){const r=statementReport;el('tutorialReport').hidden=false;el('tutorialReport').innerHTML=`<p><b>集客力 ${Number(r.attractionBefore??state.attraction).toFixed(2)} → ${Number(r.attractionAfter??state.attraction).toFixed(2)}</b> ／ 月末の品揃え ${r.assortment?`${r.assortment.stocked}/${r.assortment.total}種類`:"—"} ／ 自然減 −${Number(r.naturalLoss||0).toFixed(3)}・過去の努力の実り ＋${Number(r.effortGain||0).toFixed(3)} ／ 季節のリピーター ＋${Number(r.seasonalGain||0).toFixed(2)}</p>${r.effortPlanned?'<p>今月の営業努力は将来への種まき。集客投資の効果は翌月から出て、販促・接客改善は４か月、釣り大会の協賛は６か月で消えます、セールのリピーター効果は翌年の同じ月からです。</p>':''}${r.tax?.assessed?`<p>決算の法人税等 ${fmt(r.tax.assessed)} を計上。５月の納付に備えて預金を残しましょう。</p>`:''}${r.tax?.paid?`<p>今月の法人税等納付 ${fmt(r.tax.paid)}。損益は計上済みなので、納付で二重に費用にはしません。</p>`:''}`;};
renderPlanning=function(){if(choice.action==='sales'&&!E.sponsorEvent(state))choice.action='tend';renderPersonal();const a=currentAction(),closed=state.closed,m=month(state.turn);el('turnLabel').textContent=`第${fy(state.turn)}期 ${m}月 · TURN ${state.turn}`;el('headerCash').textContent=fmt(cash());el('ownerCash').textContent=fmt(state.owner);el('runway').textContent=`預金は固定費・返済等の約${Math.max(0,cash()/(E.fixedCosts(state)+E.scheduled(state).principal+E.scheduled(state).interest+E.scheduled(state).tax)).toFixed(1)}か月`;el('sceneSeason').textContent=[6,7,8,9,10].includes(m)?'釣りの繁忙期':[12,1,2].includes(m)?'冬の閑散期':'港町のいつもの一日';el('forecast').textContent=closed?'今月の帳簿は確定しました':`第${fy(state.turn)}期 ${m}月の経営`;el('crowd').textContent=state.attraction>1.1?'にぎわい':state.attraction<.85?'集客低下':'普通';el('orderAmount').textContent=fmt(orderCost());el('sideOrder').textContent='▲'+fmt(orderCost());el('sideAction').textContent=actionCost()?'▲'+fmt(actionCost()):'0千円';const outlook=E.forecast(state,choice.quantities,choice.price,a),after=outlook?outlook.expected:cash()-orderCost()-actionCost();el('cashPreview').textContent=fmt(after);el('previewDelta').textContent=outlook?'月末見込み（返済・納税込み）／需要下振れ時 '+fmt(outlook.low):'仕入・行動支払後。数量を確認してください';renderCashPlan(outlook);el('cashMeter').style.width=Math.min(100,Math.max(0,after/10000000*100))+'%';let error=closed?'':E.validation(state,choice.quantities,a);el('commit').disabled=!!error||!!state.ended||state.turn>=120&&closed;el('commit').textContent=state.ended?'支払不能 · 経営終了':state.turn>=120&&closed?'10期の経営を完了':closed?'次の月へ':error||'今月を確定する';el('staffAdvice').textContent=`経営者１人・従業員${state.staff.length}人。`+(a==='improve'?'販促と接客を改善。クエの接客力は今月８割です。':a==='tend'?(state.storeDutyTurn===state.turn?'店番がいないので、今月はクエが店番です（店番以外の行動はできません。誰かを店に回すと選べます）。':'今月はクエが店番します。'):state.staff.length?'今月は従業員が店番します。':'社長不在のため今月の販売は０。仕入や維持費は発生します。');document.querySelector('#staffAdvice').previousElementSibling.querySelector('.tag').textContent=state.storeDutyTurn===state.turn?'店番に固定':state.actionLocked?'今月の行動は確定済み':'月に１つ';el('actions').innerHTML=`<button class="action ${a==='tend'?'active':''}" data-value="tend" ${state.actionLocked&&state.storeDutyTurn!==state.turn||closed?'disabled':''}><img class="action-portrait" src="assets/characters/que.png" alt=""><b>店番する</b><small>接客して販売する</small></button>${E.sponsorEvent(state)?`<button class="action ${a==='sales'?'active':''} sponsor-event" data-value="sales" ${state.actionLocked||closed?'disabled':''}><span class="icon">🎣</span><b>集客投資 · 釣り大会の協賛募集！</b><small>11万円（税込）・翌月から６か月効果・今月だけのチャンス</small></button>`:`<button class="action ${a==='improve'?'active':''}" data-value="improve" ${state.actionLocked||closed?'disabled':''}><span class="icon">📣</span><b>集客投資 · 販促・接客改善</b><small>3.3万円（税込）・翌月から４か月効果</small></button>`}<button class="action" id="hireStaff" ${state.actionLocked||closed||state.staff.length>=3?'disabled':''}><span class="icon">👤</span><b>スタッフを採用</b><small>職種ごとに接客力と給与が変わる</small></button>`;renderOrders();renderOverview();renderTutorial();animateScene();if(state.turn>=120&&state.closed){el('cashPlan').innerHTML+='<button id="showFinalResult">10期の経営結果を見る</button>';}document.querySelectorAll('#prices button').forEach(b=>{b.classList.toggle('active',b.dataset.value===choice.price);b.disabled=closed;});document.querySelectorAll('#orders input,#orders button').forEach(b=>b.disabled=closed||state.ended||b.dataset.step<0&&!(choice.quantities[Number(b.dataset.product)]>0));};
function captureSave(){return {version:7,state,choice,lastReport,monthClosed:state.closed,seen:[...seenEntries],introComplete:true,animationQueue,entryStage,animationReturn:animationReturn||null};}
saveGame=function(){if(!introComplete)return;try{E.compact(state);localStorage.setItem(SAVE_KEY,JSON.stringify(captureSave()));storageError='';}catch{storageError='保存できませんでした。空き容量やブラウザ設定を確認してください。';toast(storageError);}};
introAdvance=function(){if(introEntry&&introStage===0){introStage=1;el('introJournal').innerHTML=transactionView(introEntry);el('introNext').textContent=introStep<STARTUP_LENGTH()?startupEntries[introStep].memo+' · '+fmt(startupEntries[introStep].amount):'店を開く';return;}if(introStep<STARTUP_LENGTH()){const i=introStep,begin=state.entries.length;E.applyStartup(state,i);const mainEntry=state.entries.findLast(e=>e.memo===E.STARTUP[i].memo);const recorded={...mainEntry,after:{...state.balances},introVAT:i>=2&&state.vatEnabled?E.vat(mainEntry.amount):0};for(const e of state.entries.slice(begin))seenEntries.add(entryKey(e));introStep++;el('introCash').innerHTML=amountText(cash())+'<span> 千円</span>';el('introCapital').innerHTML=amountText(state.balances.資本金)+'<span> 千円</span>';introEntry=recorded;introStage=0;el('introJournal').innerHTML=transactionView(recorded).split('<div class="entry-arrow"')[0];el('introTitle').textContent=recorded.memo;el('introSpeech').textContent=['資本金を払い込んで会社の預金になったで。','店舗の敷金は差入保証金として資産に残るんやな。','棚やレジを買ったで。この棚やレジは資産にして、使い始めてから毎月、減価償却費として経費にするんやな。','商品を並べたで。まだ売ってへんから、原価のまま資産に残るんやな。'][i];el('introNext').textContent='B/S・P/Lの増減を見る';el('introNote').textContent=`開業の取引 ${introStep} / ${STARTUP_LENGTH()}`;}else finishIntro();};
function STARTUP_LENGTH(){return E.STARTUP.length;}
function finishIntro(){state.opening={...state.balances};introComplete=true;monthClosed=false;choice.quantities=E.recommend(state);choice.orderSource='recommended';el('intro').classList.add('hidden');document.querySelector('.shell').inert=false;renderPlanning();saveGame();}
function skipIntro(){while(introStep<STARTUP_LENGTH()){const begin=state.entries.length;E.applyStartup(state,introStep++);for(const e of state.entries.slice(begin))seenEntries.add(entryKey(e));}finishIntro();}
closeMonth=function(confirmed=false){if(state.closed||state.ended)return;const f=E.forecast(state,choice.quantities,choice.price,currentAction());if(!confirmed&&f&&f.low<0){openShop('月末の資金不足に注意',`<p>月末預金の見込み ${fmt(f.expected)}、需要下振れ時 ${fmt(f.low)}。仕入・返済・納税を含みます。資金不足の場合は最後の資金繰り対応へ進み、調達できなければ経営終了です。</p><button id="replanCash">経営判断を見直す</button><button id="confirmRiskMonth">この内容で確定する</button>`);return;}try{const result=E.run(state,choice.quantities,choice.price,currentAction());state=result.state;lastReport=result.report;monthClosed=true;renderPlanning();saveGame();showNewEntries(lastReport.entries);}catch(e){toast(e.message);}};
advanceMonth=function(){if(!state.closed||state.ended||state.turn>=120)return;const priorQuantities=[...choice.quantities];state=E.next(state);monthClosed=false;choice={quantities:priorQuantities,price:'list',action:'tend',orderSource:'prior'};closeStatements();renderPlanning();saveGame();window.scrollTo({top:0,behavior:'smooth'});};
const previousOpenStatements=openStatements;
function currentStatementReport(){const opening=state.opening||state.balances;return {turn:state.turn,month:month(state.turn),fy:fy(state.turn),previousClose:{...(state.previousClose||state.history.at(-1)?.balances||opening)},before:{...opening},after:{...state.balances},entries:state.entries.filter(e=>e.turn===state.turn),opening:opening.預金,inflow:0,outflow:0,cashSales:0,cardSales:0,collected:0,spend:0,extra:state.pendingInvestment||0,fixedCash:0,served:0,customers:0,waste:0,monthProfit:E.profit(state.balances)-E.profit(opening),provisional:true};}
openStatements=function(){financialMode='month';financialYear=Math.max(1,Math.floor(((state.closed?lastReport?.turn:state.turn)||0)/12));reportFocus=document.activeElement;statementReport=state.closed&&lastReport?lastReport:currentStatementReport();tab='tb';renderReport();el('monthlyDetails').hidden=!state.closed;el('tutorialReport').hidden=!state.closed;el('next').hidden=!state.closed||state.ended||state.turn>=120;el('planning').inert=true;document.querySelector('.top').inert=true;el('report').classList.add('show');el('report').scrollTop=0;document.body.style.overflow='hidden';el('closeReport').focus();};
const previousRenderReport=renderReport;
renderReport=function(){previousRenderReport();el('headerCash').textContent=fmt(cash());if(statementReport.provisional){el('resultChips').innerHTML='<span class="chip">未確定：現在までに実行した取引だけを表示</span>';return;}el('resultChips').innerHTML=`<span class="chip">来店 ${statementReport.visitors||0}人 / 上限 ${statementReport.limit||950}人</span><span class="chip">接客 ${statementReport.served}人</span><span class="chip">廃棄・死亡 ${fmt(statementReport.waste)}</span><span class="chip">今月の損益 ${fmt(statementReport.monthProfit)}</span>${state.ended?'<span class="chip negative">支払不能。今後の取引は停止しました。</span>':''}`;};
entryKey=function(e){return e.type||e.debit+'|'+e.credit;};
function tutorialSceneKey(e){if(['saleCash','saleCard','costOfSales','vatOutput'].includes(e.type))return 'sales';if(['officerSocial','役員報酬|預金','法定福利費|預金','地代家賃|預金','広告宣伝費|預金','雑費|預金','vatInput'].includes(entryKey(e)))return 'operations';if(e.type==='depreciation')return 'depreciation';return entryKey(e);}
function groupFirstEntries(entries){const groups=[];for(const e of entries){const key=tutorialSceneKey(e),last=groups.at(-1);if(last&&last.groupId===key)last.entries.push(e);else groups.push({tutorialGroup:true,groupId:key,entries:[e]});}return groups.map(g=>g.tutorialGroup?{...g,memo:g.groupId==='sales'?'商品の販売と原価':g.groupId==='operations'?'毎月の店舗運営費':g.groupId==='depreciation'?'設備を使った分の費用化':g.entries[0].memo,before:g.entries[0].before,after:g.entries.at(-1).after}:g);}
function transactionGroupView(g){const rows=g.entries.map(e=>`<div class="entry-journal"><div><small>借方</small><b>${e.debit}</b><strong>${fmt(e.amount)}</strong></div><span>／</span><div><small>貸方</small><b>${e.credit}</b><strong>${fmt(e.amount)}</strong></div></div>`).join('');const journal=g.entries.length>4?`<details class="entry-breakdown"><summary>仕訳 ${g.entries.length} 本を詳しく見る</summary>${rows}</details>`:rows,accounts=journalAccounts(g.entries);return `<p>黄色は仕訳の借方・貸方にある科目。合計や利益の増減はその結果です。</p>${journal}<div class="entry-arrow">↓ 帳簿へ反映</div>${transactionAccountingLesson(g.entries,g.after)}${formalBalance(g.after,g.before,'今回の取引',true,accounts)}${formalPL(g.after,g.before,'今回の取引',true,null,accounts)}`;}
showNewEntries=function(entries){const keys=new Set(seenEntries),unseen=entries.filter(e=>!keys.has(entryKey(e)));animationQueue=groupFirstEntries(unseen);animationReturn=null;entryStage=0;if(animationQueue.length)showTransaction();else openStatements();};
showTransaction=function(){const e=animationQueue[0];if(!e)return;el('transactionTitle').textContent=e.memo;el('transactionCount').textContent=animationReturn?'仕訳を振り返る':`初めての取引 · 残り${animationQueue.length}シーン`;const full=e.tutorialGroup?transactionGroupView(e):transactionView(e);el('transactionBody').innerHTML=entryStage===0&&!e.tutorialGroup?full.split('<div class="entry-arrow"')[0]+'<p class="entry-step-hint">この取引で、どの科目が動くでしょう？</p>':full;el('transactionNext').textContent=entryStage===0&&!e.tutorialGroup?'B/S・P/Lの増減を見る':animationQueue.length>1?'次のシーンへ':animationReturn?'仕訳ログへ戻る':'試算表へ';document.querySelector('.shell').inert=true;el('journalOverlay').inert=true;el('transactionOverlay').hidden=false;document.body.style.overflow='hidden';el('transactionNext').focus();saveGame();};
nextTransaction=function(){const current=animationQueue[0];if(!current)return;if(entryStage===0&&!current.tutorialGroup){entryStage=1;showTransaction();return;}const returnTo=animationReturn;if(!returnTo){for(const e of current.tutorialGroup?current.entries:[current])seenEntries.add(entryKey(e));}animationQueue.shift();entryStage=0;if(animationQueue.length){showTransaction();return;}animationReturn=null;el('transactionOverlay').hidden=true;el('journalOverlay').inert=false;if(returnTo==='journal'){openJournal();saveGame();}else{document.querySelector('.shell').inert=false;saveGame();openStatements();}};
replayEntry=function(index){const e=state.entries[index-1];if(e){animationQueue=[e];animationReturn='journal';entryStage=0;showTransaction();}};
recentJournalEntries=function(){return state.entries.map((e,index)=>({...e,index})).filter(e=>e.turn>=Math.max(1,state.turn-5)&&e.turn<=state.turn);};
function showHiring(){openShop('スタッフを採用',`<p>クエの接客力は1,000人/月。採用月のクエの接客力は０。新人は採用月から通常の接客力で営業し、給与も当月から発生します。社員・店長は給与の15％の会社負担社会保険料もかかります。集客上限は別です。</p><div class="hiring-options">${Object.entries(E.ROLES).filter(([id])=>id!=='que').map(([id,r])=>`<button data-hire-preview="${id}"><b>${r.name}</b><span>接客 ${r.service.toLocaleString()}人/月</span><span>給与 ${yen(r.wage)}/月</span></button>`).join('')}</div><p>現在：${state.staff.map(x=>E.ROLES[x.role].name).join('・')||'従業員０人'}</p>`);}
function showInvestments(){openShop('設備投資',`<p class="dialog-intro">容量と品揃えを広げる。購入代金は税別。消費税10％とともにすぐに支払い、毎月の維持費も増えます。</p><p class="investment-warning">月に１回の社長の行動を使います。${state.staff.length?'購入月は従業員が店番。':'従業員０人のため、購入月は販売０です。'}</p><div class="investment-list">${Object.entries(E.EQUIPMENT).map(([id,spec])=>{const owned=state.equipment[id],locked=spec.requires&&!state.equipment[spec.requires];return `<article><div class="investment-title">${icon(id)}<div><h3>${spec.name}</h3><b>${fmt(spec.cost)}</b></div></div><p>${spec.description}</p><div class="investment-metrics"><span>維持費 ${fmt(spec.upkeep)}/月</span><span>集客上限 ＋${spec.cap}人</span></div><button data-buy-preview="${id}" ${owned||locked||state.closed||state.actionLocked||state.ended?'disabled':''}>${owned?'購入済み':locked?'冷凍庫の導入後に解放':'購入内容を確認'}</button></article>`;}).join('')}</div>`);}
function previewBuy(id){const eq=E.EQUIPMENT[id];openShop(eq.name+'を増設',`<div class="equipment-hero">${icon(id)}<p>${eq.description}</p></div><dl class="equipment-facts"><div><dt>購入代金（税込）</dt><dd>${yen(E.gross(state,eq.cost))}</dd></div><div><dt>購入後の預金</dt><dd>${yen(cash()-E.gross(state,eq.cost))}</dd></div><div><dt>毎月の維持費</dt><dd>${yen(eq.upkeep)}</dd></div><div><dt>毎月の償却費</dt><dd>${yen(Math.floor(eq.cost/eq.life))}</dd></div></dl><p>${state.staff.length?'今月は従業員が店番します。':'今月の社長は店番ができず、販売０になります。'}</p><button class="confirm" data-buy="${id}" ${cash()<E.gross(state,eq.cost)?'disabled':''}>${cash()<E.gross(state,eq.cost)?'購入資金が足りません':'購入する'}</button><p class="note">この月の仕入前に購入します。</p>`);}
function showTank(){const count=state.inventory[6],visible=Math.min(20,count);openShop('生け簀',`<div class="tank-counter"><strong>活きアジ ${count.toLocaleString()}<small>匹</small></strong><span>容量 ${count} / 300匹</span></div><div class="aquarium" role="img" aria-label="${count}匹の活きアジがいる生け簀"><div class="water-light"></div>${Array.from({length:visible},(_,i)=>`<div class="swimmer" style="--y:${12+(i*29)%66}%;--duration:${9+(i%7)}s;--delay:-${i*2.3}s;--size:${52+(i%4)*8}px"><img src="assets/equipment/aji.png" alt=""></div>`).join('')}${count===0?'<p class="empty-water">在庫なし<br><small>仕入れたアジがここで泳ぎます</small></p>':''}</div><p class="note">${count>20?'魚の表示はイメージです。実在庫は'+count+'匹。':'魚の数は在庫と連動しています。'} 見ている間は時間が進みません。</p><dl class="equipment-facts"><div><dt>在庫原価</dt><dd>${yen(count*80)}</dd></div><div><dt>維持費</dt><dd>30,000円/月</dd></div><div><dt>月次死亡ロス</dt><dd>5%（ゲーム設定）</dd></div></dl>`);}
function stockDetail(i){const p=E.PRODUCTS[i],n=state.inventory[i],available=E.unlocked(state,p);openShop(p.name,`<div class="stock-detail-icon">${productIcon(p)}</div><p class="stock-quantity">${available?n.toLocaleString()+p.unit:'未解放'}</p><dl class="equipment-facts"><div><dt>仕入単価（税抜）</dt><dd>${yen(p.cost)}</dd></div><div><dt>${p.fixedPrice?'固定売価（税抜）':'定価（税抜）'}</dt><dd>${yen(p.price)}</dd></div><div><dt>在庫原価</dt><dd>${yen(n*p.cost)}</dd></div><div><dt>保管サイズ</dt><dd>${p.size}${p.storage==='dry'?'（'+p.space/4+'pt / '+p.unit+'）':'・専用設備'}</dd></div><div><dt>回転</dt><dd>${p.turnover}</dd></div></dl><p>${p.requires&&!available?(p.requires==='tank'?'生け簀':'冷凍庫')+'を導入すると扱えます。':p.year&&!available?'２期目から扱えます。':p.life||p.obsolete?'仕入から'+(p.life||p.obsolete)+'か月で'+(p.life?'期限切れ':'陳腐化')+'により廃棄し、商品廃棄損を計上します。古い在庫から販売します。':p.id==='aji'?'毎月、入荷後の匹数の5%が死亡ロスになります。':'売れ残りは翌月へ繰り越します。'}</p>${p.id==='aji'&&state.equipment.tank?'<button id="viewTank">生け簀を見る</button>':''}`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='investMenu'){showInvestments();}else if(b.dataset.equipment){equipmentDetail(b.dataset.equipment);}else if(b.dataset.buyPreview){previewBuy(b.dataset.buyPreview);}else if(b.dataset.buy){try{state=E.buy(state,b.dataset.buy);choice.action='investment';choice.quantities=E.recommend(state,currentAction(),choice.price);choice.orderSource='recommended';closeShop();renderPlanning();saveGame();toast('設備を増設しました。店舗にアイコンが増えています。');}catch(err){toast(err.message);}}else if(b.id==='hireStaff'){showHiring();}else if(b.dataset.hirePreview){const role=b.dataset.hirePreview,r=E.ROLES[role],social=role==='parttime'?0:Math.floor(r.wage*.15);openShop('採用条件の確認',`<p><b>${r.name}</b>を今月から採用します。</p><dl class="equipment-facts"><div><dt>月給</dt><dd>${yen(r.wage)}</dd></div><div><dt>会社負担社会保険</dt><dd>${yen(social)}</dd></div><div><dt>採用月の接客力</dt><dd>${r.service.toLocaleString()}人</dd></div><div><dt>翌月以降の接客力</dt><dd>${r.service.toLocaleString()}人</dd></div></dl><p>採用は今月の行動を使い、給与は満額発生します。</p><button id="cancelHire">戻って見直す</button><button class="confirm" data-confirm-hire="${role}">この条件で採用する</button>`);}else if(b.dataset.confirmHire){try{state=E.hire(state,b.dataset.confirmHire);choice.action='hire';choice.quantities=E.recommend(state,currentAction(),choice.price);choice.orderSource='recommended';closeShop();renderPlanning();saveGame();}catch(err){toast(err.message);}}else if(b.id==='cancelHire'){showHiring();}else if(b.dataset.stock!==undefined){stockDetail(Number(b.dataset.stock));}else if(b.id==='closeShopDialog'){closeShop();}else if(b.id==='viewTank'){showTank();}else if(b.id==='recommendOrder'){choice.quantities=E.recommend(state,currentAction(),choice.price);choice.orderSource='recommended';renderPlanning();saveGame();}else if(b.id==='openFullLedger'){openStatements();}else if(b.id==='skipIntro'){skipIntro();}else if(b.id==='newGame'){showNewGameConfirmation();}else if(b.id==='confirmNewGame'){restartGame();}},false);
// Intercept special buttons before the old delegated action/order handlers.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&(b.id==='recommendOrder'||b.id==='hireStaff')){e.stopImmediatePropagation();if(b.id==='recommendOrder'){choice.quantities=E.recommend(state,currentAction(),choice.price);choice.orderSource='recommended';renderPlanning();saveGame();}else{showHiring();}}},true);
el('shopDialog').addEventListener('cancel',e=>{e.preventDefault();closeShop();});
el('shopDialog').addEventListener('click',e=>{if(e.target===el('shopDialog'))closeShop();});
const skip=document.createElement('button');skip.id='skipIntro';skip.className='skip-intro';skip.textContent='説明を飛ばして開店';el('introNext').after(skip);
const reset=document.createElement('button');reset.id='newGame';reset.className='help-top';reset.textContent='最初から始める';document.querySelector('.top').append(reset);
function renderCashPlan(f){let target=el('cashPlan');if(!target){target=document.createElement('section');target.id='cashPlan';target.className='learning-panel';el('commit').after(target);}const debt=E.scheduled(state);const due=(state.loans||[]).some(l=>l.kind==='short'&&l.balance>0&&(l.due||l.start+l.months)-state.turn<=1);target.innerHTML=`<b>月末預金の見込み ${f?fmt(f.expected):'—'}</b><p>元金返済 ${fmt(debt.principal)} ／ 利息 ${yen(debt.interest)} ／ 納税 ${fmt(debt.tax)}</p>${f?`<p>需要が10％下振れした場合 ${fmt(f.low)}。予測は確約ではありません。</p>`:''}${due?'<p class="negative">短期借入の期日が近づいています。銀行メニューから書き換えを相談できます。</p>':''}`;}
function showFinalResult(){const v=bsValues(state.balances),net=state.history.filter(h=>h.turn%12===0).reduce((n,h)=>n+E.profit(h.balances),0);openShop('10期の経営結果',`<p>純資産 <b>${fmt(v.equity)}</b></p><p>10期累計利益 <b>${fmt(net)}</b></p><p>財務スコア <b>${bankAssessment(annualSeries(),state.balances).score??'—'}</b></p><p>借入残高は純資産に反映済みです。預金の多さだけでは評価しません。</p>`);}
document.addEventListener('click',e=>{const id=e.target.closest('button')?.id;if(id==='confirmRiskMonth'){closeShop();closeMonth(true);}else if(id==='replanCash')closeShop();else if(id==='showFinalResult')showFinalResult();});
let loaded=false;try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if([4,5,6,7].includes(saved?.version)){saved.state=E.migrate(saved.state);E.assertState(saved.state);state=saved.state;choice=saved.choice;E.PRODUCTS.forEach((p,i)=>{if(p.retired)choice.quantities[i]=0;});lastReport=saved.lastReport?JSON.parse(JSON.stringify(saved.lastReport).replaceAll('内装','建物附属設備')):null;monthClosed=state.closed;seenEntries=new Set(saved.seen||[]);if(seenEntries.has('商品|預金'))seenEntries.add('purchaseCash');introComplete=true;introStep=STARTUP_LENGTH();el('intro').classList.add('hidden');document.querySelector('.shell').inert=false;loaded=true;animationQueue=saved.animationQueue||[];entryStage=saved.entryStage||0;animationReturn=saved.animationReturn||null;}}catch{toast('保存データを読み込めませんでした。元のデータは残しています。');}
if(!loaded&&(localStorage.getItem('finance-game-v3')||localStorage.getItem('finance-game-v2')))el('introNote').textContent='商品の価格・保管容量・接客力を更新しました。旧セーブは保持し、新しい店で始めます。';
renderPlanning();if(loaded&&animationQueue.length){if(animationReturn==='journal')openJournal();showTransaction();}

// The same beginner guide is available after the opening tutorial.
renderAccountingGuide(null);
